import React from 'react';
import Slider from 'react-slick';
import { Box, Container, Button } from '@mui/material';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';

// Slider içeriği
const slides = [
  {
    id: 1,
    image: "https://cdn.gcp.techcareer.net/luxoft_hackathon_1112x412_3468c22c84/luxoft_hackathon_1112x412_3468c22c84.png",
    link: "https://www.techcareer.net/hackathon/luxoft-parking-hackathon",
    alt: "Luxoft Parking Hackathon",
  },
  {
    id: 2,
    image: "https://cdn.gcp.techcareer.net/2024_duyurular_1112x412_ccf8c238f3/2024_duyurular_1112x412_ccf8c238f3.png",
    link: "https://survey.alchemer.com/s3/8068418/N240021",
    alt: "TechReport2024 Yazılımcı Anketi",
  },
];

const EventsSlider = () => {
  // Slick Slider ayarları
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 5000,
    fade: true,
    arrows: true,
    prevArrow: <CustomArrow direction="prev" />,
    nextArrow: <CustomArrow direction="next" />,
  };

  // Özel Arrow bileşeni
  const CustomArrow = ({ direction, ...props }) => (
    <Box
      {...props}
      sx={{
        position: 'absolute',
        top: '50%',
        zIndex: 2,
        width: '60px',
        height: '60px',
        backgroundColor: '#ffffff',
        borderRadius: '50%',
        boxShadow: '0 4px 8px rgba(0, 0, 0, 0.2)',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        cursor: 'pointer',
        transition: 'all 0.3s ease',
        '&:hover': {
          transform: 'scale(1.1)',
        },
        [direction === 'prev' ? 'left' : 'right']: '20px',
        transform: 'translateY(-50%)',
      }}
    >
      <Box
        component="span"
        sx={{
          fontSize: '28px',
          color: '#00C26D', // Yeşil ok rengi
          fontWeight: 'bold',
          display: 'block',
          lineHeight: '1',
        }}
      >
        {direction === 'prev' ? '<' : '>'}
      </Box>
    </Box>
  );

  return (
    <Box sx={{ backgroundColor: '#F5F9FF', py: 4, position: 'relative' }}>
      {/* Dekoratif Süsler */}
      <Box sx={{ position: 'absolute', top: '20px', left: '20px', zIndex: 1 }}>
        <img
          src="https://www.techcareer.net/assets/images/call-to-actions/home/shape-dots.svg"
          alt=""
          style={{ width: '50px', height: '50px' }}
          draggable="false"
        />
      </Box>
      <Box sx={{ position: 'absolute', top: '20px', right: '20px', zIndex: 1 }}>
        <img
          src="https://www.techcareer.net/assets/images/call-to-actions/home/kesik-yan-cizgi.svg"
          alt=""
          style={{ width: '142px', height: '142px' }}
          draggable="false"
        />
      </Box>

      {/* Slider */}
      <Container maxWidth="lg" sx={{ position: 'relative', zIndex: 2 }}>
        <Slider {...settings}>
          {slides.map((slide) => (
            <Box key={slide.id}>
              <Button
                component="a"
                href={slide.link}
                sx={{
                  p: 0,
                  borderRadius: 2,
                  overflow: 'hidden',
                  display: 'block',
                  textDecoration: 'none',
                  '&:hover': {
                    boxShadow: '0 8px 24px rgba(0, 0, 0, 0.15)',
                  },
                }}
              >
                <Box
                  sx={{
                    position: 'relative',
                    '&::after': {
                      content: '""',
                      position: 'absolute',
                      top: '10px',
                      right: '-20px', // Sağ taraftaki gölge
                      bottom: '-20px', // Alt taraftaki gölge
                      width: 'calc(100% + 20px)',
                      height: 'calc(100% + 20px)',
                      background:
                        'linear-gradient(to bottom right, transparent 50%, #00C26D 100%)',
                      borderRadius: '12px',
                      zIndex: -1,
                    },
                  }}
                >
                  <img
                    src={slide.image}
                    alt={slide.alt}
                    style={{
                      width: '100%',
                      height: 'auto',
                      maxHeight: '412px',
                      borderRadius: '8px',
                      objectFit: 'cover',
                      boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)',
                    }}
                    draggable="false"
                  />
                </Box>
              </Button>
            </Box>
          ))}
        </Slider>
      </Container>
    </Box>
  );
};

export default EventsSlider;
